insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-17','en-a1-17',null,1,17,'published',1,'{"id":"en-a1-17","baseId":"en-a1-17","revision":1,"level":"A1","levelIndex":1,"order":17,"title":"Oziq-ovqat: some, any, much va many","objective":"Sanaladigan va sanalmaydigan narsalar miqdorini aytasiz.","context":"Sinf kichik sayr uchun oziq-ovqat ro‘yxatini tuzadi.","prerequisites":["en-a1-16"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Apple sanaladi: one apple, three apples. Water odatda sanalmaydi: some water; a bottle of water birlik idishni beradi.","Many ko‘plik sanaladigan ot, much sanalmaydigan ot bilan: many apples, much water. A lot of ikkisi bilan ishlaydi.","Some ko‘pincha tasdiqda, any inkor/savolda. Taklif yoki iltimosda some ham tabiiy: Would you like some water?"],"pattern":"some apples / some water; many apples / much water; any in questions","examples":["We have some apples.","There isn’t any milk.","Do you have any bread?","How many bottles are there?","How much water do we need?","Would you like some tea?"],"vocabulary":[{"id":"en-a1-17-v0","term":"bread","meaning":"non","ipa":"/bred/","collocation":"some bread","example":"Do you have any bread?"},{"id":"en-a1-17-v1","term":"milk","meaning":"sut","ipa":"/mɪlk/","collocation":"a glass of milk","example":"There isn’t any milk."},{"id":"en-a1-17-v2","term":"bottle","meaning":"shisha yoki idish","ipa":"/ˈbɒtəl/","collocation":"a bottle of water","example":"How many bottles are there?"},{"id":"en-a1-17-v3","term":"need","meaning":"kerak bo‘lmoq","ipa":"/niːd/","collocation":"need some water","example":"How much water do we need?"}],"visuals":[{"kind":"menu","title":"Ma’no va tuzilish","items":["some apples / some water; many apples / much water; any in questions","We have some apples.","There isn’t any milk."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Sinf kichik sayr uchun oziq-ovqat ro‘yxatini tuzadi.","Do you have any bread?","How much water do we need?"]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"How many bottles are there?","audio":"/english-course/v7.23/en-a1-17-dictation.mp3"},"exercises":[{"id":"en-a1-17-choice","type":"choice","skill":"grammar","prompt":"Inkor gapni to‘ldiring: There isn’t ___ milk.","answers":["any"],"explanation":"Milk sanalmaydi, inkorda any.","hint":"some apples / some water; many apples / much water; any in questions","options":["any","many","a"]},{"id":"en-a1-17-gap","type":"grammarFill","skill":"grammar","prompt":"How ___ apples are there?","answers":["many"],"explanation":"Apple sanaladi: one apple, three apples. Water odatda sanalmaydi: some water; a bottle of water birlik idishni beradi. Many ko‘plik sanaladigan ot, much sanalmaydigan ot bilan: many apples, much water. A lot of ikkisi bilan ishlaydi. Some ko‘pincha tasdiqda, any inkor/savolda. Taklif yoki iltimosda some ham tabiiy: Would you like some water?","hint":"some apples / some water; many apples / much water; any in questions"},{"id":"en-a1-17-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["We have some apples."],"explanation":"Apple sanaladi: one apple, three apples. Water odatda sanalmaydi: some water; a bottle of water birlik idishni beradi. Many ko‘plik sanaladigan ot, much sanalmaydigan ot bilan: many apples, much water. A lot of ikkisi bilan ishlaydi. Some ko‘pincha tasdiqda, any inkor/savolda. Taklif yoki iltimosda some ham tabiiy: Would you like some water?","hint":"some apples / some water; many apples / much water; any in questions","tokens":["We","have","some","apples."]},{"id":"en-a1-17-fix","type":"correction","skill":"grammar","prompt":"How many water do we need?","answers":["How much water do we need?"],"explanation":"Apple sanaladi: one apple, three apples. Water odatda sanalmaydi: some water; a bottle of water birlik idishni beradi. Many ko‘plik sanaladigan ot, much sanalmaydigan ot bilan: many apples, much water. A lot of ikkisi bilan ishlaydi. Some ko‘pincha tasdiqda, any inkor/savolda. Taklif yoki iltimosda some ham tabiiy: Would you like some water?","hint":"some apples / some water; many apples / much water; any in questions"},{"id":"en-a1-17-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["non","sut","shisha yoki idish","kerak bo‘lmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"some apples / some water; many apples / much water; any in questions","left":["bread","milk","bottle","need"],"options":["non","sut","shisha yoki idish","kerak bo‘lmoq"]}],"reading":{"title":"Oziq-ovqat: some, any, much va many — vaziyat","text":"Our class is preparing for a picnic. We have some apples and a lot of bread. There isn’t any milk because we cannot keep it cold. Ali asks how many bottles of water we need. Lola says that we need six bottles for the small group. We do not need much sugar. The teacher asks everyone to bring a reusable cup and not leave any rubbish in the park.","sentences":["Our class is preparing for a picnic.","We have some apples and a lot of bread.","There isn’t any milk because we cannot keep it cold.","Ali asks how many bottles of water we need.","Lola says that we need six bottles for the small group.","We do not need much sugar.","The teacher asks everyone to bring a reusable cup and not leave any rubbish in the park."],"questions":[{"id":"en-a1-17-reading0","type":"choice","skill":"reading","prompt":"Nega sut olinmaydi?","answers":["they cannot keep it cold"],"explanation":"Because we cannot keep it cold.","hint":"some apples / some water; many apples / much water; any in questions","options":["they cannot keep it cold","everyone dislikes it","it is too heavy"]},{"id":"en-a1-17-reading1","type":"choice","skill":"reading","prompt":"Nechta suv idishi kerak?","answers":["six"],"explanation":"We need six bottles.","hint":"some apples / some water; many apples / much water; any in questions","options":["six","four","ten"]},{"id":"en-a1-17-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"some apples / some water; many apples / much water; any in questions","options":["Our class is preparing for a picnic.","We have some apples and a lot of bread.","There isn’t any milk because we cannot keep it cold.","Ali asks how many bottles of water we need.","Lola says that we need six bottles for the small group.","We do not need much sugar.","The teacher asks everyone to bring a reusable cup and not leave any rubbish in the park."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"We have some apples and bread. We don’t have any milk. Please bring six bottles of water. We don’t need much sugar. Bring a reusable cup too.","audio":"/english-course/v7.23/en-a1-17.mp3","synthetic":true,"questions":[{"id":"en-a1-17-listening0","type":"choice","skill":"listening","prompt":"Nima yo‘q?","answers":["milk"],"explanation":"We don’t have any milk.","hint":"some apples / some water; many apples / much water; any in questions","options":["milk","bread","apples"]},{"id":"en-a1-17-listening1","type":"choice","skill":"listening","prompt":"Suv idishlari soni?","answers":["six"],"explanation":"Six bottles of water.","hint":"some apples / some water; many apples / much water; any in questions","options":["six","three","eight"]},{"id":"en-a1-17-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["six","milk"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"some apples / some water; many apples / much water; any in questions","rows":["Suv idishi","Yo‘q mahsulot"]},{"id":"en-a1-17-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["How many bottles are there?"],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"some apples / some water; many apples / much water; any in questions","audio":"/english-course/v7.23/en-a1-17-dictation.mp3","transcript":"How many bottles are there?"}]},"writing":{"task":"Sayr uchun bor va kerak mahsulotlar ro‘yxatini gaplar bilan yozing.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"We have some apples and a lot of bread. We don’t have any milk. How many bottles of water do we need? We need six. Please bring a reusable cup. We don’t need much sugar for our tea.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["We have some apples.","There isn’t any milk.","Do you have any bread?"],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Do‘konda yoki sayr uchun mahsulot miqdorini so‘rab suhbat qiling.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Sayr uchun bor va kerak mahsulotlar ro‘yxatini gaplar bilan yozing.","exit":[[{"id":"en-a1-17-exit0","type":"grammarFill","skill":"grammar","prompt":"How ___ water?","answers":["much"],"explanation":"Apple sanaladi: one apple, three apples. Water odatda sanalmaydi: some water; a bottle of water birlik idishni beradi. Many ko‘plik sanaladigan ot, much sanalmaydigan ot bilan: many apples, much water. A lot of ikkisi bilan ishlaydi. Some ko‘pincha tasdiqda, any inkor/savolda. Taklif yoki iltimosda some ham tabiiy: Would you like some water?","hint":"some apples / some water; many apples / much water; any in questions"},{"id":"en-a1-17-exit1","type":"grammarFill","skill":"grammar","prompt":"How ___ bottles?","answers":["many"],"explanation":"Apple sanaladi: one apple, three apples. Water odatda sanalmaydi: some water; a bottle of water birlik idishni beradi. Many ko‘plik sanaladigan ot, much sanalmaydigan ot bilan: many apples, much water. A lot of ikkisi bilan ishlaydi. Some ko‘pincha tasdiqda, any inkor/savolda. Taklif yoki iltimosda some ham tabiiy: Would you like some water?","hint":"some apples / some water; many apples / much water; any in questions"},{"id":"en-a1-17-exit2","type":"grammarFill","skill":"grammar","prompt":"We have ___ apples. (ba’zi)","answers":["some"],"explanation":"Apple sanaladi: one apple, three apples. Water odatda sanalmaydi: some water; a bottle of water birlik idishni beradi. Many ko‘plik sanaladigan ot, much sanalmaydigan ot bilan: many apples, much water. A lot of ikkisi bilan ishlaydi. Some ko‘pincha tasdiqda, any inkor/savolda. Taklif yoki iltimosda some ham tabiiy: Would you like some water?","hint":"some apples / some water; many apples / much water; any in questions"},{"id":"en-a1-17-exit3","type":"choice","skill":"grammar","prompt":"Bir suv birligi uchun mos ibora qaysi?","answers":["a bottle of water"],"explanation":"Idish birlikni sanaladigan qiladi.","hint":"some apples / some water; many apples / much water; any in questions","options":["a bottle of water","a water (ordinary quantity)","many water"]},{"id":"en-a1-17-exit4","type":"choice","skill":"grammar","prompt":"Taklifda some ishlatilishi mumkinmi?","answers":["Yes"],"explanation":"Would you like some tea? — tabiiy taklif.","hint":"some apples / some water; many apples / much water; any in questions","options":["Yes","No","Only in the past"]}],[{"id":"en-a1-17-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["There isn’t any milk."],"explanation":"Apple sanaladi: one apple, three apples. Water odatda sanalmaydi: some water; a bottle of water birlik idishni beradi. Many ko‘plik sanaladigan ot, much sanalmaydigan ot bilan: many apples, much water. A lot of ikkisi bilan ishlaydi. Some ko‘pincha tasdiqda, any inkor/savolda. Taklif yoki iltimosda some ham tabiiy: Would you like some water?","hint":"some apples / some water; many apples / much water; any in questions","tokens":["There","isn’t","any","milk."]},{"id":"en-a1-17-exit-b1","type":"grammarFill","skill":"grammar","prompt":"How ___ bottles?","answers":["many"],"explanation":"Apple sanaladi: one apple, three apples. Water odatda sanalmaydi: some water; a bottle of water birlik idishni beradi. Many ko‘plik sanaladigan ot, much sanalmaydigan ot bilan: many apples, much water. A lot of ikkisi bilan ishlaydi. Some ko‘pincha tasdiqda, any inkor/savolda. Taklif yoki iltimosda some ham tabiiy: Would you like some water?","hint":"some apples / some water; many apples / much water; any in questions"},{"id":"en-a1-17-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["How many bottles are there?"],"explanation":"Apple sanaladi: one apple, three apples. Water odatda sanalmaydi: some water; a bottle of water birlik idishni beradi. Many ko‘plik sanaladigan ot, much sanalmaydigan ot bilan: many apples, much water. A lot of ikkisi bilan ishlaydi. Some ko‘pincha tasdiqda, any inkor/savolda. Taklif yoki iltimosda some ham tabiiy: Would you like some water?","hint":"some apples / some water; many apples / much water; any in questions","tokens":["How","many","bottles","are","there?"]},{"id":"en-a1-17-exit-b3","type":"choice","skill":"grammar","prompt":"Bir suv birligi uchun mos ibora qaysi?","answers":["a bottle of water"],"explanation":"Idish birlikni sanaladigan qiladi.","hint":"some apples / some water; many apples / much water; any in questions","options":["a bottle of water","a water (ordinary quantity)","many water"]},{"id":"en-a1-17-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Would you like some tea?"],"explanation":"Apple sanaladi: one apple, three apples. Water odatda sanalmaydi: some water; a bottle of water birlik idishni beradi. Many ko‘plik sanaladigan ot, much sanalmaydigan ot bilan: many apples, much water. A lot of ikkisi bilan ishlaydi. Some ko‘pincha tasdiqda, any inkor/savolda. Taklif yoki iltimosda some ham tabiiy: Would you like some water?","hint":"some apples / some water; many apples / much water; any in questions","tokens":["Would","you","like","some","tea?"]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-18','en-a1-18',null,1,18,'published',1,'{"id":"en-a1-18","baseId":"en-a1-18","revision":1,"level":"A1","levelIndex":1,"order":18,"title":"Like + -ing va bog‘langan tanishtirish","objective":"Qiziqish, oila va kun tartibini and, but, because bilan bog‘lab taqdim etasiz.","context":"A1 yakunida yangi sinfdoshga o‘zingiz haqingizda xat yozasiz.","prerequisites":["en-a1-17"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Like/enjoy dan keyin bu darsda -ing shakli ishlatiladi: I like reading. Like bilan to-infinitive ham ayrim kontekstlarda mumkin, lekin enjoy to read emas.","And qo‘shimcha fikr, but farq, because sababni bog‘laydi. Har bir gapni bitta juda uzun zanjirga aylantirmang.","Tanishtirishni tartiblang: kimligim → oila → odat → qiziqish. Savolga mos tafsilot bering; yodlangan gaplarni vaziyatsiz takrorlamang."],"pattern":"I like reading, but I don’t like … . I enjoy … because … .","examples":["I like reading stories.","She enjoys drawing.","I like football, but I don’t play every day.","We read because stories are interesting.","My sister and I study together.","I am a student, and I live in Samarkand."],"vocabulary":[{"id":"en-a1-18-v0","term":"enjoy","meaning":"zavqlanmoq","ipa":"/ɪnˈdʒɔɪ/","collocation":"enjoy drawing","example":"She enjoys drawing."},{"id":"en-a1-18-v1","term":"story","meaning":"hikoya","ipa":"/ˈstɔːri/","collocation":"read a story","example":"read a story"},{"id":"en-a1-18-v2","term":"live","meaning":"yashamoq","ipa":"/lɪv/","collocation":"live in Samarkand","example":"I am a student, and I live in Samarkand."},{"id":"en-a1-18-v3","term":"free time","meaning":"bo‘sh vaqt","ipa":"/friː taɪm/","collocation":"in my free time","example":"In my free time, I like reading stories because they help me imagine new places."}],"visuals":[{"kind":"story","title":"Ma’no va tuzilish","items":["I like reading, but I don’t like … . I enjoy … because … .","I like reading stories.","She enjoys drawing."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["A1 yakunida yangi sinfdoshga o‘zingiz haqingizda xat yozasiz.","I like football, but I don’t play every day.","My sister and I study together."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"We read because stories are interesting.","audio":"/english-course/v7.23/en-a1-18-dictation.mp3"},"exercises":[{"id":"en-a1-18-choice","type":"choice","skill":"grammar","prompt":"Sababni bog‘lovchi so‘zni tanlang.","answers":["because"],"explanation":"Because sababni beradi.","hint":"I like reading, but I don’t like … . I enjoy … because … .","options":["because","but","and"]},{"id":"en-a1-18-gap","type":"grammarFill","skill":"grammar","prompt":"She enjoys ___. (draw)","answers":["drawing"],"explanation":"Like/enjoy dan keyin bu darsda -ing shakli ishlatiladi: I like reading. Like bilan to-infinitive ham ayrim kontekstlarda mumkin, lekin enjoy to read emas. And qo‘shimcha fikr, but farq, because sababni bog‘laydi. Har bir gapni bitta juda uzun zanjirga aylantirmang. Tanishtirishni tartiblang: kimligim → oila → odat → qiziqish. Savolga mos tafsilot bering; yodlangan gaplarni vaziyatsiz takrorlamang.","hint":"I like reading, but I don’t like … . I enjoy … because … ."},{"id":"en-a1-18-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I like reading stories."],"explanation":"Like/enjoy dan keyin bu darsda -ing shakli ishlatiladi: I like reading. Like bilan to-infinitive ham ayrim kontekstlarda mumkin, lekin enjoy to read emas. And qo‘shimcha fikr, but farq, because sababni bog‘laydi. Har bir gapni bitta juda uzun zanjirga aylantirmang. Tanishtirishni tartiblang: kimligim → oila → odat → qiziqish. Savolga mos tafsilot bering; yodlangan gaplarni vaziyatsiz takrorlamang.","hint":"I like reading, but I don’t like … . I enjoy … because … .","tokens":["I","like","reading","stories."]},{"id":"en-a1-18-fix","type":"correction","skill":"grammar","prompt":"I enjoy to read.","answers":["I enjoy reading."],"explanation":"Like/enjoy dan keyin bu darsda -ing shakli ishlatiladi: I like reading. Like bilan to-infinitive ham ayrim kontekstlarda mumkin, lekin enjoy to read emas. And qo‘shimcha fikr, but farq, because sababni bog‘laydi. Har bir gapni bitta juda uzun zanjirga aylantirmang. Tanishtirishni tartiblang: kimligim → oila → odat → qiziqish. Savolga mos tafsilot bering; yodlangan gaplarni vaziyatsiz takrorlamang.","hint":"I like reading, but I don’t like … . I enjoy … because … ."},{"id":"en-a1-18-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["zavqlanmoq","hikoya","yashamoq","bo‘sh vaqt"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"I like reading, but I don’t like … . I enjoy … because … .","left":["enjoy","story","live","free time"],"options":["zavqlanmoq","hikoya","yashamoq","bo‘sh vaqt"]},{"id":"en-a1-18-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["enjoy","story","live","free time"],"options":["enjoy drawing","read a story","live in Samarkand","in my free time"],"answers":["enjoy drawing","read a story","live in Samarkand","in my free time"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Like + -ing va bog‘langan tanishtirish — vaziyat","text":"Hello, my name is Lola. I am thirteen, and I live in Samarkand. I have a brother and a sister. We study at the same school. I usually walk to school, but my brother goes by bus. In my free time, I like reading stories because they help me imagine new places. My sister enjoys drawing. On Fridays, we go to a small reading club and talk about our favourite books.","sentences":["Hello, my name is Lola.","I am thirteen, and I live in Samarkand.","I have a brother and a sister.","We study at the same school.","I usually walk to school, but my brother goes by bus.","In my free time, I like reading stories because they help me imagine new places.","My sister enjoys drawing.","On Fridays, we go to a small reading club and talk about our favourite books."],"questions":[{"id":"en-a1-18-reading0","type":"choice","skill":"reading","prompt":"Lola nega hikoya o‘qishni yoqtiradi?","answers":["they help her imagine places"],"explanation":"Because they help me imagine new places.","hint":"I like reading, but I don’t like … . I enjoy … because … .","options":["they help her imagine places","she must do it for work","her brother dislikes them"]},{"id":"en-a1-18-reading1","type":"choice","skill":"reading","prompt":"Uning singlisi nimani yoqtiradi?","answers":["drawing"],"explanation":"My sister enjoys drawing.","hint":"I like reading, but I don’t like … . I enjoy … because … .","options":["drawing","running","cooking"]},{"id":"en-a1-18-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"I like reading, but I don’t like … . I enjoy … because … .","options":["Hello, my name is Lola.","I am thirteen, and I live in Samarkand.","I have a brother and a sister.","We study at the same school.","I usually walk to school, but my brother goes by bus.","In my free time, I like reading stories because they help me imagine new places.","My sister enjoys drawing.","On Fridays, we go to a small reading club and talk about our favourite books."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"I am Lola, and I live in Samarkand. I like reading stories because I can imagine new places. My sister enjoys drawing. We go to the reading club on Fridays, but my brother prefers football.","audio":"/english-course/v7.23/en-a1-18.mp3","synthetic":true,"questions":[{"id":"en-a1-18-listening0","type":"choice","skill":"listening","prompt":"Lola qayerda yashaydi?","answers":["Samarkand"],"explanation":"Live in Samarkand.","hint":"I like reading, but I don’t like … . I enjoy … because … .","options":["Samarkand","Tashkent","Bukhara"]},{"id":"en-a1-18-listening1","type":"choice","skill":"listening","prompt":"Kitobxonlar to‘garagi kuni qaysi?","answers":["Fridays"],"explanation":"On Fridays deyiladi.","hint":"I like reading, but I don’t like … . I enjoy … because … .","options":["Fridays","Mondays","Sundays"]},{"id":"en-a1-18-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["Samarkand","Fridays"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"I like reading, but I don’t like … . I enjoy … because … .","rows":["Shahar","To‘garak kuni"]},{"id":"en-a1-18-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["We read because stories are interesting."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"I like reading, but I don’t like … . I enjoy … because … .","audio":"/english-course/v7.23/en-a1-18-dictation.mp3","transcript":"We read because stories are interesting."}]},"writing":{"task":"A1 loyiha: yangi sinfdoshga o‘zingiz, oilangiz, kun tartibingiz va qiziqishingiz haqida xat yozing.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Hi Ali, I am Lola, and I live in Samarkand. I have a brother and a sister. I usually walk to school. In my free time, I like reading because stories are interesting. My sister enjoys drawing, but my brother likes football. What do you enjoy doing?","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["I like reading stories.","She enjoys drawing.","I like football, but I don’t play every day."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"O‘zingizni bir daqiqagacha tanishtiring. Sherigingizning ikkita savoliga javob bering.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Yangi to‘garakda o‘zingizni tanishtiring va sherigingizning ikki qiziqishini aniqlang.","exit":[[{"id":"en-a1-18-exit0","type":"grammarFill","skill":"grammar","prompt":"I like ___ stories. (read)","answers":["reading"],"explanation":"Like/enjoy dan keyin bu darsda -ing shakli ishlatiladi: I like reading. Like bilan to-infinitive ham ayrim kontekstlarda mumkin, lekin enjoy to read emas. And qo‘shimcha fikr, but farq, because sababni bog‘laydi. Har bir gapni bitta juda uzun zanjirga aylantirmang. Tanishtirishni tartiblang: kimligim → oila → odat → qiziqish. Savolga mos tafsilot bering; yodlangan gaplarni vaziyatsiz takrorlamang.","hint":"I like reading, but I don’t like … . I enjoy … because … ."},{"id":"en-a1-18-exit1","type":"grammarFill","skill":"grammar","prompt":"She enjoys ___. (draw)","answers":["drawing"],"explanation":"Like/enjoy dan keyin bu darsda -ing shakli ishlatiladi: I like reading. Like bilan to-infinitive ham ayrim kontekstlarda mumkin, lekin enjoy to read emas. And qo‘shimcha fikr, but farq, because sababni bog‘laydi. Har bir gapni bitta juda uzun zanjirga aylantirmang. Tanishtirishni tartiblang: kimligim → oila → odat → qiziqish. Savolga mos tafsilot bering; yodlangan gaplarni vaziyatsiz takrorlamang.","hint":"I like reading, but I don’t like … . I enjoy … because … ."},{"id":"en-a1-18-exit2","type":"grammarFill","skill":"grammar","prompt":"I like it ___ it is useful.","answers":["because"],"explanation":"Like/enjoy dan keyin bu darsda -ing shakli ishlatiladi: I like reading. Like bilan to-infinitive ham ayrim kontekstlarda mumkin, lekin enjoy to read emas. And qo‘shimcha fikr, but farq, because sababni bog‘laydi. Har bir gapni bitta juda uzun zanjirga aylantirmang. Tanishtirishni tartiblang: kimligim → oila → odat → qiziqish. Savolga mos tafsilot bering; yodlangan gaplarni vaziyatsiz takrorlamang.","hint":"I like reading, but I don’t like … . I enjoy … because … ."},{"id":"en-a1-18-exit3","type":"choice","skill":"grammar","prompt":"Farqni bog‘lash uchun qaysi so‘z?","answers":["but"],"explanation":"But ikki fikr orasidagi farqni ko‘rsatadi.","hint":"I like reading, but I don’t like … . I enjoy … because … .","options":["but","and","because"]},{"id":"en-a1-18-exit4","type":"choice","skill":"grammar","prompt":"Enjoy bilan to‘g‘ri shakl qaysi?","answers":["enjoy reading"],"explanation":"Enjoy dan keyin -ing.","hint":"I like reading, but I don’t like … . I enjoy … because … .","options":["enjoy reading","enjoy to read","enjoy reads"]}],[{"id":"en-a1-18-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["She enjoys drawing."],"explanation":"Like/enjoy dan keyin bu darsda -ing shakli ishlatiladi: I like reading. Like bilan to-infinitive ham ayrim kontekstlarda mumkin, lekin enjoy to read emas. And qo‘shimcha fikr, but farq, because sababni bog‘laydi. Har bir gapni bitta juda uzun zanjirga aylantirmang. Tanishtirishni tartiblang: kimligim → oila → odat → qiziqish. Savolga mos tafsilot bering; yodlangan gaplarni vaziyatsiz takrorlamang.","hint":"I like reading, but I don’t like … . I enjoy … because … .","tokens":["She","enjoys","drawing."]},{"id":"en-a1-18-exit-b1","type":"grammarFill","skill":"grammar","prompt":"She enjoys ___. (draw)","answers":["drawing"],"explanation":"Like/enjoy dan keyin bu darsda -ing shakli ishlatiladi: I like reading. Like bilan to-infinitive ham ayrim kontekstlarda mumkin, lekin enjoy to read emas. And qo‘shimcha fikr, but farq, because sababni bog‘laydi. Har bir gapni bitta juda uzun zanjirga aylantirmang. Tanishtirishni tartiblang: kimligim → oila → odat → qiziqish. Savolga mos tafsilot bering; yodlangan gaplarni vaziyatsiz takrorlamang.","hint":"I like reading, but I don’t like … . I enjoy … because … ."},{"id":"en-a1-18-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We read because stories are interesting."],"explanation":"Like/enjoy dan keyin bu darsda -ing shakli ishlatiladi: I like reading. Like bilan to-infinitive ham ayrim kontekstlarda mumkin, lekin enjoy to read emas. And qo‘shimcha fikr, but farq, because sababni bog‘laydi. Har bir gapni bitta juda uzun zanjirga aylantirmang. Tanishtirishni tartiblang: kimligim → oila → odat → qiziqish. Savolga mos tafsilot bering; yodlangan gaplarni vaziyatsiz takrorlamang.","hint":"I like reading, but I don’t like … . I enjoy … because … .","tokens":["We","read","because","stories","are","interesting."]},{"id":"en-a1-18-exit-b3","type":"choice","skill":"grammar","prompt":"Farqni bog‘lash uchun qaysi so‘z?","answers":["but"],"explanation":"But ikki fikr orasidagi farqni ko‘rsatadi.","hint":"I like reading, but I don’t like … . I enjoy … because … .","options":["but","and","because"]},{"id":"en-a1-18-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I am a student, and I live in Samarkand."],"explanation":"Like/enjoy dan keyin bu darsda -ing shakli ishlatiladi: I like reading. Like bilan to-infinitive ham ayrim kontekstlarda mumkin, lekin enjoy to read emas. And qo‘shimcha fikr, but farq, because sababni bog‘laydi. Har bir gapni bitta juda uzun zanjirga aylantirmang. Tanishtirishni tartiblang: kimligim → oila → odat → qiziqish. Savolga mos tafsilot bering; yodlangan gaplarni vaziyatsiz takrorlamang.","hint":"I like reading, but I don’t like … . I enjoy … because … .","tokens":["I","am","a","student,","and","I","live","in","Samarkand."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":true,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-01','en-a2-01',null,2,1,'published',1,'{"id":"en-a2-01","baseId":"en-a2-01","revision":1,"level":"A2","levelIndex":2,"order":1,"title":"Was va were: kechagi holat","objective":"O‘tmishdagi joy va holatni aytasiz.","context":"Sinfdoshlar kechagi ekskursiya haqida gaplashadi.","prerequisites":["en-a1-18"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["To be ning o‘tgan shakli I/he/she/it bilan was, you/we/they bilan were. Yesterday, last week kabi vaqtlar o‘tmishni aniqlaydi.","Wasn’t va weren’t inkor; Was she …? yoki Were they …? savol. Bu savollarga did qo‘shilmaydi.","O‘tgan holatni harakat bilan aralashtirmang: We were tired — holat; We walked — harakat. Was tired va was walking boshqa tuzilmalar."],"pattern":"was / were; Was she there? No, she wasn’t.","examples":["We were at the museum yesterday.","I was tired after the trip.","Lola wasn’t late.","Were the rooms open?","Yes, they were.","The weather was sunny."],"vocabulary":[{"id":"en-a2-01-v0","term":"museum","meaning":"muzey","ipa":"/mjuːˈziːəm/","collocation":"visit a museum","example":"We were at the museum yesterday."},{"id":"en-a2-01-v1","term":"tired","meaning":"charchagan","ipa":"/ˈtaɪəd/","collocation":"be tired","example":"I was tired after the trip."},{"id":"en-a2-01-v2","term":"trip","meaning":"safar","ipa":"/trɪp/","collocation":"a school trip","example":"I was tired after the trip."},{"id":"en-a2-01-v3","term":"sunny","meaning":"quyoshli","ipa":"/ˈsʌni/","collocation":"sunny weather","example":"The weather was sunny."}],"visuals":[{"kind":"timeline","title":"Ma’no va tuzilish","items":["was / were; Was she there? No, she wasn’t.","We were at the museum yesterday.","I was tired after the trip."],"timeline":[{"why":"Yesterday holatni tugagan o‘tgan vaqtga bog‘laydi. We bilan were ishlatiladi.","events":[{"kind":"point","x":145,"label":"Kecha muzeyda bo‘lish"}]},{"why":"Was tired safardan keyingi o‘tgan holat. Safarning sanasi aytilmagan.","events":[{"kind":"point","x":185,"label":"Safardan keyin charchagan"}]}]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Sinfdoshlar kechagi ekskursiya haqida gaplashadi.","Lola wasn’t late.","Yes, they were."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Were the rooms open?","audio":"/english-course/v7.23/en-a2-01-dictation.mp3"},"exercises":[{"id":"en-a2-01-choice","type":"choice","skill":"grammar","prompt":"I ___ at home last night.","answers":["was"],"explanation":"I uchun o‘tmishda was.","hint":"was / were; Was she there? No, she wasn’t.","options":["was","were","am"]},{"id":"en-a2-01-gap","type":"grammarFill","skill":"grammar","prompt":"We ___ tired yesterday.","answers":["were"],"explanation":"To be ning o‘tgan shakli I/he/she/it bilan was, you/we/they bilan were. Yesterday, last week kabi vaqtlar o‘tmishni aniqlaydi. Wasn’t va weren’t inkor; Was she …? yoki Were they …? savol. Bu savollarga did qo‘shilmaydi. O‘tgan holatni harakat bilan aralashtirmang: We were tired — holat; We walked — harakat. Was tired va was walking boshqa tuzilmalar.","hint":"was / were; Was she there? No, she wasn’t."},{"id":"en-a2-01-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["We were at the museum yesterday."],"explanation":"To be ning o‘tgan shakli I/he/she/it bilan was, you/we/they bilan were. Yesterday, last week kabi vaqtlar o‘tmishni aniqlaydi. Wasn’t va weren’t inkor; Was she …? yoki Were they …? savol. Bu savollarga did qo‘shilmaydi. O‘tgan holatni harakat bilan aralashtirmang: We were tired — holat; We walked — harakat. Was tired va was walking boshqa tuzilmalar.","hint":"was / were; Was she there? No, she wasn’t.","tokens":["We","were","at","the","museum","yesterday."]},{"id":"en-a2-01-fix","type":"correction","skill":"grammar","prompt":"Did she was there?","answers":["Was she there?"],"explanation":"To be ning o‘tgan shakli I/he/she/it bilan was, you/we/they bilan were. Yesterday, last week kabi vaqtlar o‘tmishni aniqlaydi. Wasn’t va weren’t inkor; Was she …? yoki Were they …? savol. Bu savollarga did qo‘shilmaydi. O‘tgan holatni harakat bilan aralashtirmang: We were tired — holat; We walked — harakat. Was tired va was walking boshqa tuzilmalar.","hint":"was / were; Was she there? No, she wasn’t."},{"id":"en-a2-01-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["muzey","charchagan","safar","quyoshli"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"was / were; Was she there? No, she wasn’t.","left":["museum","tired","trip","sunny"],"options":["muzey","charchagan","safar","quyoshli"]}],"reading":{"title":"Was va were: kechagi holat — vaziyat","text":"Yesterday our class was at a history museum. The weather was sunny, so we walked from the bus stop. Lola was early, but two students were late. The rooms were open, and the guide was friendly. There were old maps and pictures of the city. After the visit, we were tired but happy. The café wasn’t open, so we ate our lunch in the park. Today we are writing about the trip and comparing our favourite objects.","sentences":["Yesterday our class was at a history museum.","The weather was sunny, so we walked from the bus stop.","Lola was early, but two students were late.","The rooms were open, and the guide was friendly.","There were old maps and pictures of the city.","After the visit, we were tired but happy.","The café wasn’t open, so we ate our lunch in the park.","Today we are writing about the trip and comparing our favourite objects."],"questions":[{"id":"en-a2-01-reading0","type":"choice","skill":"reading","prompt":"Nega bog‘da tushlik qilishdi?","answers":["the café wasn’t open"],"explanation":"The café wasn’t open — sabab.","hint":"was / were; Was she there? No, she wasn’t.","options":["the café wasn’t open","the guide was late","there were no maps"]},{"id":"en-a2-01-reading1","type":"choice","skill":"reading","prompt":"Ekskursiyadan keyin qanday edi?","answers":["tired but happy"],"explanation":"We were tired but happy.","hint":"was / were; Was she there? No, she wasn’t.","options":["tired but happy","angry and hungry","bored"]},{"id":"en-a2-01-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"was / were; Was she there? No, she wasn’t.","options":["Yesterday our class was at a history museum.","The weather was sunny, so we walked from the bus stop.","Lola was early, but two students were late.","The rooms were open, and the guide was friendly.","There were old maps and pictures of the city.","After the visit, we were tired but happy.","The café wasn’t open, so we ate our lunch in the park.","Today we are writing about the trip and comparing our favourite objects."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"We were at the museum yesterday. Lola was early. Two students were late. The guide was friendly, but the café wasn’t open. We ate in the park.","audio":"/english-course/v7.23/en-a2-01.mp3","synthetic":true,"questions":[{"id":"en-a2-01-listening0","type":"choice","skill":"listening","prompt":"Nechta o‘quvchi kechikdi?","answers":["two"],"explanation":"Two students were late.","hint":"was / were; Was she there? No, she wasn’t.","options":["two","three","one"]},{"id":"en-a2-01-listening1","type":"choice","skill":"listening","prompt":"Kafe ochiqmidi?","answers":["No"],"explanation":"Wasn’t open — inkor.","hint":"was / were; Was she there? No, she wasn’t.","options":["No","Yes","Only for the guide"]},{"id":"en-a2-01-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["two","park"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"was / were; Was she there? No, she wasn’t.","rows":["Kechikkanlar soni","Tushlik joyi"]},{"id":"en-a2-01-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Were the rooms open?"],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"was / were; Was she there? No, she wasn’t.","audio":"/english-course/v7.23/en-a2-01-dictation.mp3","transcript":"Were the rooms open?"}]},"writing":{"task":"Kecha bo‘lgan joyingiz va holatingiz haqida qisqa xabar yozing.","audience":"Sinfdagi sherigingiz","minWords":55,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Yesterday I was at the museum with my class. The weather was sunny, and our guide was friendly. There were old maps in one room. I was interested in a picture of our city. After the visit, we were tired, but we were happy. The café wasn’t open, so our lunch was in the park.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["We were at the museum yesterday.","I was tired after the trip.","Lola wasn’t late."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Kecha qayerda bo‘lganingizni va qanday his qilganingizni ayting.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Kecha bo‘lgan joyingiz va holatingiz haqida qisqa xabar yozing.","exit":[[{"id":"en-a2-01-exit0","type":"grammarFill","skill":"grammar","prompt":"They ___ at the museum.","answers":["were"],"explanation":"To be ning o‘tgan shakli I/he/she/it bilan was, you/we/they bilan were. Yesterday, last week kabi vaqtlar o‘tmishni aniqlaydi. Wasn’t va weren’t inkor; Was she …? yoki Were they …? savol. Bu savollarga did qo‘shilmaydi. O‘tgan holatni harakat bilan aralashtirmang: We were tired — holat; We walked — harakat. Was tired va was walking boshqa tuzilmalar.","hint":"was / were; Was she there? No, she wasn’t."},{"id":"en-a2-01-exit1","type":"grammarFill","skill":"grammar","prompt":"She ___ late. (inkor)","answers":["wasn’t"],"explanation":"To be ning o‘tgan shakli I/he/she/it bilan was, you/we/they bilan were. Yesterday, last week kabi vaqtlar o‘tmishni aniqlaydi. Wasn’t va weren’t inkor; Was she …? yoki Were they …? savol. Bu savollarga did qo‘shilmaydi. O‘tgan holatni harakat bilan aralashtirmang: We were tired — holat; We walked — harakat. Was tired va was walking boshqa tuzilmalar.","hint":"was / were; Was she there? No, she wasn’t."},{"id":"en-a2-01-exit2","type":"grammarFill","skill":"grammar","prompt":"___ you tired yesterday?","answers":["Were"],"explanation":"To be ning o‘tgan shakli I/he/she/it bilan was, you/we/they bilan were. Yesterday, last week kabi vaqtlar o‘tmishni aniqlaydi. Wasn’t va weren’t inkor; Was she …? yoki Were they …? savol. Bu savollarga did qo‘shilmaydi. O‘tgan holatni harakat bilan aralashtirmang: We were tired — holat; We walked — harakat. Was tired va was walking boshqa tuzilmalar.","hint":"was / were; Was she there? No, she wasn’t."},{"id":"en-a2-01-exit3","type":"choice","skill":"grammar","prompt":"Holatni bildiradigan gapni tanlang.","answers":["We were tired."],"explanation":"Were + sifat holatni aytadi.","hint":"was / were; Was she there? No, she wasn’t.","options":["We were tired.","We were walk.","We did tired."]},{"id":"en-a2-01-exit4","type":"choice","skill":"grammar","prompt":"Yesterday vaqtini tanlang.","answers":["past"],"explanation":"Yesterday kecha.","hint":"was / were; Was she there? No, she wasn’t.","options":["past","future","always present"]}],[{"id":"en-a2-01-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I was tired after the trip."],"explanation":"To be ning o‘tgan shakli I/he/she/it bilan was, you/we/they bilan were. Yesterday, last week kabi vaqtlar o‘tmishni aniqlaydi. Wasn’t va weren’t inkor; Was she …? yoki Were they …? savol. Bu savollarga did qo‘shilmaydi. O‘tgan holatni harakat bilan aralashtirmang: We were tired — holat; We walked — harakat. Was tired va was walking boshqa tuzilmalar.","hint":"was / were; Was she there? No, she wasn’t.","tokens":["I","was","tired","after","the","trip."]},{"id":"en-a2-01-exit-b1","type":"grammarFill","skill":"grammar","prompt":"She ___ late. (inkor)","answers":["wasn’t"],"explanation":"To be ning o‘tgan shakli I/he/she/it bilan was, you/we/they bilan were. Yesterday, last week kabi vaqtlar o‘tmishni aniqlaydi. Wasn’t va weren’t inkor; Was she …? yoki Were they …? savol. Bu savollarga did qo‘shilmaydi. O‘tgan holatni harakat bilan aralashtirmang: We were tired — holat; We walked — harakat. Was tired va was walking boshqa tuzilmalar.","hint":"was / were; Was she there? No, she wasn’t."},{"id":"en-a2-01-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Were the rooms open?"],"explanation":"To be ning o‘tgan shakli I/he/she/it bilan was, you/we/they bilan were. Yesterday, last week kabi vaqtlar o‘tmishni aniqlaydi. Wasn’t va weren’t inkor; Was she …? yoki Were they …? savol. Bu savollarga did qo‘shilmaydi. O‘tgan holatni harakat bilan aralashtirmang: We were tired — holat; We walked — harakat. Was tired va was walking boshqa tuzilmalar.","hint":"was / were; Was she there? No, she wasn’t.","tokens":["Were","the","rooms","open?"]},{"id":"en-a2-01-exit-b3","type":"choice","skill":"grammar","prompt":"Holatni bildiradigan gapni tanlang.","answers":["We were tired."],"explanation":"Were + sifat holatni aytadi.","hint":"was / were; Was she there? No, she wasn’t.","options":["We were tired.","We were walk.","We did tired."]},{"id":"en-a2-01-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The weather was sunny."],"explanation":"To be ning o‘tgan shakli I/he/she/it bilan was, you/we/they bilan were. Yesterday, last week kabi vaqtlar o‘tmishni aniqlaydi. Wasn’t va weren’t inkor; Was she …? yoki Were they …? savol. Bu savollarga did qo‘shilmaydi. O‘tgan holatni harakat bilan aralashtirmang: We were tired — holat; We walked — harakat. Was tired va was walking boshqa tuzilmalar.","hint":"was / were; Was she there? No, she wasn’t.","tokens":["The","weather","was","sunny."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a2-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a2-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a2-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a2-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a2-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a2-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a2-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a2-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-02','en-a2-02',null,2,2,'published',1,'{"id":"en-a2-02","baseId":"en-a2-02","revision":1,"level":"A2","levelIndex":2,"order":2,"title":"Past Simple: tugallangan ish va did","objective":"O‘tmishdagi tugallangan voqeani savol va inkor bilan ifodalaysiz.","context":"Oila dam olish kunida nima qilganini eslaydi.","prerequisites":["en-a2-01"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Muntazam fe’llarga odatda -ed qo‘shiladi: visit → visited, play → played. Live → lived, study → studied imlosini farqlang.","Savol va inkorda did/didn’t + asosiy shakl: Did you visit? We didn’t visit. Did you visited noto‘g‘ri.","Past Simple tugallangan o‘tmish voqeasini aytadi. Yesterday va last Sunday kabi vaqt bilan ishlatiladi; vaqt ko‘rinmasa ham kontekst o‘tmishni belgilashi mumkin."],"pattern":"visited / Did you visit? / didn’t visit","examples":["We visited our grandparents.","I played football on Sunday.","She studied in the library.","Did you watch the film?","We didn’t stay late.","They arrived at six."],"vocabulary":[{"id":"en-a2-02-v0","term":"visit","meaning":"tashrif buyurmoq","ipa":"/ˈvɪzɪt/","collocation":"visit grandparents","example":"We visited our grandparents."},{"id":"en-a2-02-v1","term":"arrive","meaning":"yetib kelmoq","ipa":"/əˈraɪv/","collocation":"arrive at six","example":"They arrived at six."},{"id":"en-a2-02-v2","term":"stay","meaning":"qolmoq","ipa":"/steɪ/","collocation":"stay late","example":"We didn’t stay late."},{"id":"en-a2-02-v3","term":"grandparents","meaning":"bobo va buvi","ipa":"/ˈɡrænpeərənts/","collocation":"our grandparents","example":"We visited our grandparents."}],"visuals":[{"kind":"timeline","title":"Ma’no va tuzilish","items":["visited / Did you visit? / didn’t visit","We visited our grandparents.","I played football on Sunday."],"timeline":[{"why":"Visited — tugallangan o‘tgan harakat; aniq sanani bu gapning o‘zi bermaydi.","events":[{"kind":"point","x":150,"label":"Tugallangan tashrif"}]},{"why":"On Sunday tugagan yakshanba vaqtini belgilaydi. Played shu vaqtdagi harakat.","events":[{"kind":"point","x":155,"label":"O‘tgan yakshanbadagi o‘yin"}]}]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Oila dam olish kunida nima qilganini eslaydi.","She studied in the library.","We didn’t stay late."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Did you watch the film?","audio":"/english-course/v7.23/en-a2-02-dictation.mp3"},"exercises":[{"id":"en-a2-02-choice","type":"choice","skill":"grammar","prompt":"O‘tgan savolni tanlang.","answers":["Did you visit the village?"],"explanation":"Did + visit asosiy shakl.","hint":"visited / Did you visit? / didn’t visit","options":["Did you visit the village?","Did you visited the village?","Do you visited the village?"]},{"id":"en-a2-02-gap","type":"grammarFill","skill":"grammar","prompt":"Did you ___ the film? (watch)","answers":["watch"],"explanation":"Muntazam fe’llarga odatda -ed qo‘shiladi: visit → visited, play → played. Live → lived, study → studied imlosini farqlang. Savol va inkorda did/didn’t + asosiy shakl: Did you visit? We didn’t visit. Did you visited noto‘g‘ri. Past Simple tugallangan o‘tmish voqeasini aytadi. Yesterday va last Sunday kabi vaqt bilan ishlatiladi; vaqt ko‘rinmasa ham kontekst o‘tmishni belgilashi mumkin.","hint":"visited / Did you visit? / didn’t visit"},{"id":"en-a2-02-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["We visited our grandparents."],"explanation":"Muntazam fe’llarga odatda -ed qo‘shiladi: visit → visited, play → played. Live → lived, study → studied imlosini farqlang. Savol va inkorda did/didn’t + asosiy shakl: Did you visit? We didn’t visit. Did you visited noto‘g‘ri. Past Simple tugallangan o‘tmish voqeasini aytadi. Yesterday va last Sunday kabi vaqt bilan ishlatiladi; vaqt ko‘rinmasa ham kontekst o‘tmishni belgilashi mumkin.","hint":"visited / Did you visit? / didn’t visit","tokens":["We","visited","our","grandparents."]},{"id":"en-a2-02-fix","type":"correction","skill":"grammar","prompt":"We didn’t stayed late.","answers":["We didn’t stay late."],"explanation":"Muntazam fe’llarga odatda -ed qo‘shiladi: visit → visited, play → played. Live → lived, study → studied imlosini farqlang. Savol va inkorda did/didn’t + asosiy shakl: Did you visit? We didn’t visit. Did you visited noto‘g‘ri. Past Simple tugallangan o‘tmish voqeasini aytadi. Yesterday va last Sunday kabi vaqt bilan ishlatiladi; vaqt ko‘rinmasa ham kontekst o‘tmishni belgilashi mumkin.","hint":"visited / Did you visit? / didn’t visit"},{"id":"en-a2-02-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["tashrif buyurmoq","yetib kelmoq","qolmoq","bobo va buvi"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"visited / Did you visit? / didn’t visit","left":["visit","arrive","stay","grandparents"],"options":["tashrif buyurmoq","yetib kelmoq","qolmoq","bobo va buvi"]}],"reading":{"title":"Past Simple: tugallangan ish va did — vaziyat","text":"Last Sunday we visited our grandparents in a nearby village. We arrived at ten and helped in the garden. My brother played football with our cousins. I stayed inside for a short time and listened to my grandmother’s stories. After lunch, we watched an old film. We didn’t stay late because school started the next morning. At home, I wrote three new words from the film in my notebook. Did you have a quiet Sunday too?","sentences":["Last Sunday we visited our grandparents in a nearby village.","We arrived at ten and helped in the garden.","My brother played football with our cousins.","I stayed inside for a short time and listened to my grandmother’s stories.","After lunch, we watched an old film.","We didn’t stay late because school started the next morning.","At home, I wrote three new words from the film in my notebook.","Did you have a quiet Sunday too?"],"questions":[{"id":"en-a2-02-reading0","type":"choice","skill":"reading","prompt":"Nega kechgacha qolishmadi?","answers":["school started the next morning"],"explanation":"Because school started the next morning.","hint":"visited / Did you visit? / didn’t visit","options":["school started the next morning","the film was boring","the garden was closed"]},{"id":"en-a2-02-reading1","type":"choice","skill":"reading","prompt":"So‘zlovchi kimning hikoyasini tingladi?","answers":["grandmother’s"],"explanation":"My grandmother’s stories.","hint":"visited / Did you visit? / didn’t visit","options":["grandmother’s","brother’s","teacher’s"]},{"id":"en-a2-02-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"visited / Did you visit? / didn’t visit","options":["Last Sunday we visited our grandparents in a nearby village.","We arrived at ten and helped in the garden.","My brother played football with our cousins.","I stayed inside for a short time and listened to my grandmother’s stories.","After lunch, we watched an old film.","We didn’t stay late because school started the next morning.","At home, I wrote three new words from the film in my notebook.","Did you have a quiet Sunday too?"]}]},"listening":{"title":"Suhbatni tushunish","transcript":"We visited our grandparents last Sunday. We arrived at ten and helped in the garden. My brother played football. We didn’t stay late because we had school on Monday.","audio":"/english-course/v7.23/en-a2-02.mp3","synthetic":true,"questions":[{"id":"en-a2-02-listening0","type":"choice","skill":"listening","prompt":"Qachon yetib kelishdi?","answers":["ten"],"explanation":"Arrived at ten.","hint":"visited / Did you visit? / didn’t visit","options":["ten","six","twelve"]},{"id":"en-a2-02-listening1","type":"choice","skill":"listening","prompt":"Aka yoki uka nima qildi?","answers":["played football"],"explanation":"My brother played football.","hint":"visited / Did you visit? / didn’t visit","options":["played football","watched birds","studied English"]},{"id":"en-a2-02-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["Sunday","ten"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"visited / Did you visit? / didn’t visit","rows":["Kun","Kelish soati"]},{"id":"en-a2-02-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Did you watch the film?"],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"visited / Did you visit? / didn’t visit","audio":"/english-course/v7.23/en-a2-02-dictation.mp3","transcript":"Did you watch the film?"}]},"writing":{"task":"Dam olish kunidagi uch voqeani tartib bilan yozing. Bitta qilmagan ishingizni ham ayting.","audience":"Sinfdagi sherigingiz","minWords":54,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Last Saturday I visited my cousins. We played a board game and helped prepare lunch. After lunch, we watched a short film. I liked the story, but my cousin preferred the music. We didn’t stay outside late. In the evening, I studied English for half an hour and wrote a message to my friend.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["We visited our grandparents.","I played football on Sunday.","She studied in the library."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Sherigingizdan Did you …? bilan dam olish kuni haqida so‘rang.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Dam olish kunidagi uch voqeani tartib bilan yozing. Bitta qilmagan ishingizni ham ayting.","exit":[[{"id":"en-a2-02-exit0","type":"grammarFill","skill":"grammar","prompt":"Yesterday I ___ football. (play)","answers":["played"],"explanation":"Muntazam fe’llarga odatda -ed qo‘shiladi: visit → visited, play → played. Live → lived, study → studied imlosini farqlang. Savol va inkorda did/didn’t + asosiy shakl: Did you visit? We didn’t visit. Did you visited noto‘g‘ri. Past Simple tugallangan o‘tmish voqeasini aytadi. Yesterday va last Sunday kabi vaqt bilan ishlatiladi; vaqt ko‘rinmasa ham kontekst o‘tmishni belgilashi mumkin.","hint":"visited / Did you visit? / didn’t visit"},{"id":"en-a2-02-exit1","type":"grammarFill","skill":"grammar","prompt":"She ___ English. (study)","answers":["studied"],"explanation":"Muntazam fe’llarga odatda -ed qo‘shiladi: visit → visited, play → played. Live → lived, study → studied imlosini farqlang. Savol va inkorda did/didn’t + asosiy shakl: Did you visit? We didn’t visit. Did you visited noto‘g‘ri. Past Simple tugallangan o‘tmish voqeasini aytadi. Yesterday va last Sunday kabi vaqt bilan ishlatiladi; vaqt ko‘rinmasa ham kontekst o‘tmishni belgilashi mumkin.","hint":"visited / Did you visit? / didn’t visit"},{"id":"en-a2-02-exit2","type":"grammarFill","skill":"grammar","prompt":"Did they ___ at six? (arrive)","answers":["arrive"],"explanation":"Muntazam fe’llarga odatda -ed qo‘shiladi: visit → visited, play → played. Live → lived, study → studied imlosini farqlang. Savol va inkorda did/didn’t + asosiy shakl: Did you visit? We didn’t visit. Did you visited noto‘g‘ri. Past Simple tugallangan o‘tmish voqeasini aytadi. Yesterday va last Sunday kabi vaqt bilan ishlatiladi; vaqt ko‘rinmasa ham kontekst o‘tmishni belgilashi mumkin.","hint":"visited / Did you visit? / didn’t visit"},{"id":"en-a2-02-exit3","type":"choice","skill":"grammar","prompt":"Inkorni tanlang.","answers":["We didn’t stay."],"explanation":"Didn’t shaklni o‘zi o‘tmishga olib o‘tadi.","hint":"visited / Did you visit? / didn’t visit","options":["We didn’t stay.","We didn’t stayed.","We don’t stayed."]},{"id":"en-a2-02-exit4","type":"choice","skill":"grammar","prompt":"Visit ning muntazam o‘tgan shakli?","answers":["visited"],"explanation":"Visit → visited.","hint":"visited / Did you visit? / didn’t visit","options":["visited","visitted","visiting"]}],[{"id":"en-a2-02-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I played football on Sunday."],"explanation":"Muntazam fe’llarga odatda -ed qo‘shiladi: visit → visited, play → played. Live → lived, study → studied imlosini farqlang. Savol va inkorda did/didn’t + asosiy shakl: Did you visit? We didn’t visit. Did you visited noto‘g‘ri. Past Simple tugallangan o‘tmish voqeasini aytadi. Yesterday va last Sunday kabi vaqt bilan ishlatiladi; vaqt ko‘rinmasa ham kontekst o‘tmishni belgilashi mumkin.","hint":"visited / Did you visit? / didn’t visit","tokens":["I","played","football","on","Sunday."]},{"id":"en-a2-02-exit-b1","type":"grammarFill","skill":"grammar","prompt":"She ___ English. (study)","answers":["studied"],"explanation":"Muntazam fe’llarga odatda -ed qo‘shiladi: visit → visited, play → played. Live → lived, study → studied imlosini farqlang. Savol va inkorda did/didn’t + asosiy shakl: Did you visit? We didn’t visit. Did you visited noto‘g‘ri. Past Simple tugallangan o‘tmish voqeasini aytadi. Yesterday va last Sunday kabi vaqt bilan ishlatiladi; vaqt ko‘rinmasa ham kontekst o‘tmishni belgilashi mumkin.","hint":"visited / Did you visit? / didn’t visit"},{"id":"en-a2-02-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Did you watch the film?"],"explanation":"Muntazam fe’llarga odatda -ed qo‘shiladi: visit → visited, play → played. Live → lived, study → studied imlosini farqlang. Savol va inkorda did/didn’t + asosiy shakl: Did you visit? We didn’t visit. Did you visited noto‘g‘ri. Past Simple tugallangan o‘tmish voqeasini aytadi. Yesterday va last Sunday kabi vaqt bilan ishlatiladi; vaqt ko‘rinmasa ham kontekst o‘tmishni belgilashi mumkin.","hint":"visited / Did you visit? / didn’t visit","tokens":["Did","you","watch","the","film?"]},{"id":"en-a2-02-exit-b3","type":"choice","skill":"grammar","prompt":"Inkorni tanlang.","answers":["We didn’t stay."],"explanation":"Didn’t shaklni o‘zi o‘tmishga olib o‘tadi.","hint":"visited / Did you visit? / didn’t visit","options":["We didn’t stay.","We didn’t stayed.","We don’t stayed."]},{"id":"en-a2-02-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["They arrived at six."],"explanation":"Muntazam fe’llarga odatda -ed qo‘shiladi: visit → visited, play → played. Live → lived, study → studied imlosini farqlang. Savol va inkorda did/didn’t + asosiy shakl: Did you visit? We didn’t visit. Did you visited noto‘g‘ri. Past Simple tugallangan o‘tmish voqeasini aytadi. Yesterday va last Sunday kabi vaqt bilan ishlatiladi; vaqt ko‘rinmasa ham kontekst o‘tmishni belgilashi mumkin.","hint":"visited / Did you visit? / didn’t visit","tokens":["They","arrived","at","six."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-03','en-a2-03',null,2,3,'published',1,'{"id":"en-a2-03","baseId":"en-a2-03","revision":1,"level":"A2","levelIndex":2,"order":3,"title":"Noto‘g‘ri fe’llar va o‘tgan hikoya","objective":"Go/went, see/saw, buy/bought bilan qisqa voqea aytasiz.","context":"Bozordagi yo‘qolgan daftarni topish voqeasi eslanadi.","prerequisites":["en-a2-02"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Noto‘g‘ri fe’llar -ed qoidasi bilan yasalmaydi: go → went, see → saw, buy → bought, take → took. Shaklni kontekst bilan o‘rganing.","Savolda va inkorda yana asosiy shaklga qaytamiz: Did you go? I didn’t buy. Did you went emas.","First, then, after that, finally voqealarni bog‘laydi. Har gapda o‘tmishdagi kim nima qilganini aniq ko‘rsating."],"pattern":"go → went; see → saw; buy → bought; Did you go?","examples":["I went to the market.","She saw a red notebook.","We bought some fruit.","He took the bus home.","Did you find your bag?","I didn’t buy a new pen."],"vocabulary":[{"id":"en-a2-03-v0","term":"market","meaning":"bozor","ipa":"/ˈmɑːkɪt/","collocation":"go to the market","example":"I went to the market."},{"id":"en-a2-03-v1","term":"find","meaning":"topmoq","ipa":"/faɪnd/","collocation":"find a bag","example":"Did you find your bag?"},{"id":"en-a2-03-v2","term":"fruit","meaning":"meva","ipa":"/fruːt/","collocation":"buy some fruit","example":"We bought some fruit."},{"id":"en-a2-03-v3","term":"finally","meaning":"nihoyat","ipa":"/ˈfaɪnəli/","collocation":"finally find it","example":"Finally, we took the bus home."}],"visuals":[{"kind":"sentence","title":"Ma’no va tuzilish","items":["go → went; see → saw; buy → bought; Did you go?","I went to the market.","She saw a red notebook."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Bozordagi yo‘qolgan daftarni topish voqeasi eslanadi.","We bought some fruit.","Did you find your bag?"]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"He took the bus home.","audio":"/english-course/v7.23/en-a2-03-dictation.mp3"},"exercises":[{"id":"en-a2-03-choice","type":"choice","skill":"grammar","prompt":"See ning o‘tgan shakli qaysi?","answers":["saw"],"explanation":"See → saw.","hint":"go → went; see → saw; buy → bought; Did you go?","options":["saw","seed","seeed"]},{"id":"en-a2-03-gap","type":"grammarFill","skill":"grammar","prompt":"Yesterday we ___ fruit. (buy)","answers":["bought"],"explanation":"Noto‘g‘ri fe’llar -ed qoidasi bilan yasalmaydi: go → went, see → saw, buy → bought, take → took. Shaklni kontekst bilan o‘rganing. Savolda va inkorda yana asosiy shaklga qaytamiz: Did you go? I didn’t buy. Did you went emas. First, then, after that, finally voqealarni bog‘laydi. Har gapda o‘tmishdagi kim nima qilganini aniq ko‘rsating.","hint":"go → went; see → saw; buy → bought; Did you go?"},{"id":"en-a2-03-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I went to the market."],"explanation":"Noto‘g‘ri fe’llar -ed qoidasi bilan yasalmaydi: go → went, see → saw, buy → bought, take → took. Shaklni kontekst bilan o‘rganing. Savolda va inkorda yana asosiy shaklga qaytamiz: Did you go? I didn’t buy. Did you went emas. First, then, after that, finally voqealarni bog‘laydi. Har gapda o‘tmishdagi kim nima qilganini aniq ko‘rsating.","hint":"go → went; see → saw; buy → bought; Did you go?","tokens":["I","went","to","the","market."]},{"id":"en-a2-03-fix","type":"correction","skill":"grammar","prompt":"Did you went home?","answers":["Did you go home?"],"explanation":"Noto‘g‘ri fe’llar -ed qoidasi bilan yasalmaydi: go → went, see → saw, buy → bought, take → took. Shaklni kontekst bilan o‘rganing. Savolda va inkorda yana asosiy shaklga qaytamiz: Did you go? I didn’t buy. Did you went emas. First, then, after that, finally voqealarni bog‘laydi. Har gapda o‘tmishdagi kim nima qilganini aniq ko‘rsating.","hint":"go → went; see → saw; buy → bought; Did you go?"},{"id":"en-a2-03-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["bozor","topmoq","meva","nihoyat"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"go → went; see → saw; buy → bought; Did you go?","left":["market","find","fruit","finally"],"options":["bozor","topmoq","meva","nihoyat"]},{"id":"en-a2-03-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["market","find","fruit","finally"],"options":["go to the market","find a bag","buy some fruit","finally find it"],"answers":["go to the market","find a bag","buy some fruit","finally find it"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Noto‘g‘ri fe’llar va o‘tgan hikoya — vaziyat","text":"I went to the market with my father on Saturday. First, we bought some fruit. Then I saw a small book stall and looked at the notebooks. I took my red notebook out of my bag to check its size. After that, we went to the bus stop. I couldn’t find my notebook. We walked back to the stall, and the seller gave it to me. Finally, we took the bus home. I didn’t buy a new notebook because I found my old one.","sentences":["I went to the market with my father on Saturday.","First, we bought some fruit.","Then I saw a small book stall and looked at the notebooks.","I took my red notebook out of my bag to check its size.","After that, we went to the bus stop.","I couldn’t find my notebook.","We walked back to the stall, and the seller gave it to me.","Finally, we took the bus home.","I didn’t buy a new notebook because I found my old one."],"questions":[{"id":"en-a2-03-reading0","type":"choice","skill":"reading","prompt":"Daftar qayerda qolgan edi?","answers":["at the book stall"],"explanation":"Qaytib sotuvchidan olishadi.","hint":"go → went; see → saw; buy → bought; Did you go?","options":["at the book stall","on the bus","at home"]},{"id":"en-a2-03-reading1","type":"choice","skill":"reading","prompt":"Nega yangi daftar olmadi?","answers":["he found the old one"],"explanation":"Because I found my old one.","hint":"go → went; see → saw; buy → bought; Did you go?","options":["he found the old one","the market was closed","he had no bag"]},{"id":"en-a2-03-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"go → went; see → saw; buy → bought; Did you go?","options":["I went to the market with my father on Saturday.","First, we bought some fruit.","Then I saw a small book stall and looked at the notebooks.","I took my red notebook out of my bag to check its size.","After that, we went to the bus stop.","I couldn’t find my notebook.","We walked back to the stall, and the seller gave it to me.","Finally, we took the bus home.","I didn’t buy a new notebook because I found my old one."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"I went to the market on Saturday. We bought fruit. I left my notebook at a book stall. The seller gave it back to me. Finally, we took the bus home.","audio":"/english-course/v7.23/en-a2-03.mp3","synthetic":true,"questions":[{"id":"en-a2-03-listening0","type":"choice","skill":"listening","prompt":"Kim daftarni qaytardi?","answers":["the seller"],"explanation":"The seller gave it back.","hint":"go → went; see → saw; buy → bought; Did you go?","options":["the seller","the driver","a cousin"]},{"id":"en-a2-03-listening1","type":"choice","skill":"listening","prompt":"Uyga qanday qaytishdi?","answers":["by bus"],"explanation":"Took the bus home.","hint":"go → went; see → saw; buy → bought; Did you go?","options":["by bus","on foot","by bicycle"]},{"id":"en-a2-03-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["notebook","seller"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"go → went; see → saw; buy → bought; Did you go?","rows":["Yo‘qolgan buyum","Qaytargan odam"]},{"id":"en-a2-03-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["He took the bus home."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"go → went; see → saw; buy → bought; Did you go?","audio":"/english-course/v7.23/en-a2-03-dictation.mp3","transcript":"He took the bus home."}]},"writing":{"task":"Bir buyumni topgan yoki bir joyga borgan voqeangizni first/then/finally bilan yozing.","audience":"Sinfdagi sherigingiz","minWords":54,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"On Sunday I went to the park with my sister. First, we bought some water. Then we saw a small dog near a tree. Its owner was looking for it. We told the owner where the dog was. Finally, she found it and thanked us. We took some photos and went home before lunch.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["I went to the market.","She saw a red notebook.","We bought some fruit."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Bitta o‘tgan voqeani ayting; sherigingiz kamida ikkita tafsilotni so‘rasin.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Bir buyumni topgan yoki bir joyga borgan voqeangizni first/then/finally bilan yozing.","exit":[[{"id":"en-a2-03-exit0","type":"grammarFill","skill":"grammar","prompt":"Go ning o‘tgan shakli?","answers":["went"],"explanation":"Noto‘g‘ri fe’llar -ed qoidasi bilan yasalmaydi: go → went, see → saw, buy → bought, take → took. Shaklni kontekst bilan o‘rganing. Savolda va inkorda yana asosiy shaklga qaytamiz: Did you go? I didn’t buy. Did you went emas. First, then, after that, finally voqealarni bog‘laydi. Har gapda o‘tmishdagi kim nima qilganini aniq ko‘rsating.","hint":"go → went; see → saw; buy → bought; Did you go?"},{"id":"en-a2-03-exit1","type":"grammarFill","skill":"grammar","prompt":"Take ning o‘tgan shakli?","answers":["took"],"explanation":"Noto‘g‘ri fe’llar -ed qoidasi bilan yasalmaydi: go → went, see → saw, buy → bought, take → took. Shaklni kontekst bilan o‘rganing. Savolda va inkorda yana asosiy shaklga qaytamiz: Did you go? I didn’t buy. Did you went emas. First, then, after that, finally voqealarni bog‘laydi. Har gapda o‘tmishdagi kim nima qilganini aniq ko‘rsating.","hint":"go → went; see → saw; buy → bought; Did you go?"},{"id":"en-a2-03-exit2","type":"grammarFill","skill":"grammar","prompt":"I didn’t ___ a pen. (buy)","answers":["buy"],"explanation":"Noto‘g‘ri fe’llar -ed qoidasi bilan yasalmaydi: go → went, see → saw, buy → bought, take → took. Shaklni kontekst bilan o‘rganing. Savolda va inkorda yana asosiy shaklga qaytamiz: Did you go? I didn’t buy. Did you went emas. First, then, after that, finally voqealarni bog‘laydi. Har gapda o‘tmishdagi kim nima qilganini aniq ko‘rsating.","hint":"go → went; see → saw; buy → bought; Did you go?"},{"id":"en-a2-03-exit3","type":"choice","skill":"grammar","prompt":"Savolni tanlang.","answers":["Did you see it?"],"explanation":"Did + see.","hint":"go → went; see → saw; buy → bought; Did you go?","options":["Did you see it?","Did you saw it?","Do you saw it?"]},{"id":"en-a2-03-exit4","type":"choice","skill":"grammar","prompt":"Buy ning o‘tgan shakli?","answers":["bought"],"explanation":"Buy → bought.","hint":"go → went; see → saw; buy → bought; Did you go?","options":["bought","buyed","buied"]}],[{"id":"en-a2-03-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["She saw a red notebook."],"explanation":"Noto‘g‘ri fe’llar -ed qoidasi bilan yasalmaydi: go → went, see → saw, buy → bought, take → took. Shaklni kontekst bilan o‘rganing. Savolda va inkorda yana asosiy shaklga qaytamiz: Did you go? I didn’t buy. Did you went emas. First, then, after that, finally voqealarni bog‘laydi. Har gapda o‘tmishdagi kim nima qilganini aniq ko‘rsating.","hint":"go → went; see → saw; buy → bought; Did you go?","tokens":["She","saw","a","red","notebook."]},{"id":"en-a2-03-exit-b1","type":"grammarFill","skill":"grammar","prompt":"Take ning o‘tgan shakli?","answers":["took"],"explanation":"Noto‘g‘ri fe’llar -ed qoidasi bilan yasalmaydi: go → went, see → saw, buy → bought, take → took. Shaklni kontekst bilan o‘rganing. Savolda va inkorda yana asosiy shaklga qaytamiz: Did you go? I didn’t buy. Did you went emas. First, then, after that, finally voqealarni bog‘laydi. Har gapda o‘tmishdagi kim nima qilganini aniq ko‘rsating.","hint":"go → went; see → saw; buy → bought; Did you go?"},{"id":"en-a2-03-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["He took the bus home."],"explanation":"Noto‘g‘ri fe’llar -ed qoidasi bilan yasalmaydi: go → went, see → saw, buy → bought, take → took. Shaklni kontekst bilan o‘rganing. Savolda va inkorda yana asosiy shaklga qaytamiz: Did you go? I didn’t buy. Did you went emas. First, then, after that, finally voqealarni bog‘laydi. Har gapda o‘tmishdagi kim nima qilganini aniq ko‘rsating.","hint":"go → went; see → saw; buy → bought; Did you go?","tokens":["He","took","the","bus","home."]},{"id":"en-a2-03-exit-b3","type":"choice","skill":"grammar","prompt":"Savolni tanlang.","answers":["Did you see it?"],"explanation":"Did + see.","hint":"go → went; see → saw; buy → bought; Did you go?","options":["Did you see it?","Did you saw it?","Do you saw it?"]},{"id":"en-a2-03-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I didn’t buy a new pen."],"explanation":"Noto‘g‘ri fe’llar -ed qoidasi bilan yasalmaydi: go → went, see → saw, buy → bought, take → took. Shaklni kontekst bilan o‘rganing. Savolda va inkorda yana asosiy shaklga qaytamiz: Did you go? I didn’t buy. Did you went emas. First, then, after that, finally voqealarni bog‘laydi. Har gapda o‘tmishdagi kim nima qilganini aniq ko‘rsating.","hint":"go → went; see → saw; buy → bought; Did you go?","tokens":["I","didn’t","buy","a","new","pen."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-04','en-a2-04',null,2,4,'published',1,'{"id":"en-a2-04","baseId":"en-a2-04","revision":1,"level":"A2","levelIndex":2,"order":4,"title":"Past Continuous va uzilgan harakat","objective":"O‘tmishdagi davom etayotgan ishga qisqa voqea kirishini ko‘rsatasiz.","context":"O‘quvchi uy vazifasi qilayotganda elektr o‘chib qoladi.","prerequisites":["en-a2-03"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Was/were + -ing o‘tmishdagi ma’lum paytda davom etayotgan harakatni bildiradi: I was reading at eight.","Past Simple qisqa kiruvchi voqeani beradi: I was reading when the lights went out. Ikki shakl bir hikoyada turli vazifaga ega.","While ko‘pincha davom etayotgan ikki ishni bog‘laydi. When va while ni faqat bitta zamonga qamalgan avtomatik signal deb olmang; ma’noni kuzating."],"pattern":"was/were + -ing … when + Past Simple","examples":["I was reading at eight.","The lights went out.","She was writing when I called.","We were talking while Ali was drawing.","Were you sleeping?","They weren’t watching TV."],"vocabulary":[{"id":"en-a2-04-v0","term":"lights","meaning":"chiroqlar","ipa":"/laɪts/","collocation":"the lights went out","example":"The lights went out."},{"id":"en-a2-04-v1","term":"call","meaning":"qo‘ng‘iroq qilmoq","ipa":"/kɔːl/","collocation":"call a friend","example":"She was writing when I called."},{"id":"en-a2-04-v2","term":"while","meaning":"… paytida","ipa":"/waɪl/","collocation":"while I was reading","example":"We were talking while Ali was drawing."},{"id":"en-a2-04-v3","term":"suddenly","meaning":"to‘satdan","ipa":"/ˈsʌdənli/","collocation":"suddenly stop","example":"Suddenly, the lights went out."}],"visuals":[{"kind":"timeline","title":"Ma’no va tuzilish","items":["was/were + -ing … when + Past Simple","I was reading at eight.","The lights went out."],"timeline":[{"why":"Was reading at eight — o‘tgan paytda davom etayotgan jarayon. Shu payt ichida kuzatuv bor.","events":[{"kind":"span","from":75,"to":245,"label":"O‘qish jarayoni"},{"kind":"point","x":155,"label":"O‘tgan vaqtdagi soat sakkiz"}]},{"why":"Went out — chiroq o‘chishi kabi qisqa voqea. Past Simple davom etayotgan jarayondan ajraladi.","events":[{"kind":"point","x":160,"label":"Chiroq o‘chishi"}]}]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["O‘quvchi uy vazifasi qilayotganda elektr o‘chib qoladi.","She was writing when I called.","Were you sleeping?"]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"We were talking while Ali was drawing.","audio":"/english-course/v7.23/en-a2-04-dictation.mp3"},"exercises":[{"id":"en-a2-04-choice","type":"choice","skill":"grammar","prompt":"Fon harakatni tanlang.","answers":["I was reading when she called."],"explanation":"Was + reading davom etayotgan fon.","hint":"was/were + -ing … when + Past Simple","options":["I was reading when she called.","I did reading when she call.","I were read when she called."]},{"id":"en-a2-04-gap","type":"grammarFill","skill":"grammar","prompt":"We ___ talking when he arrived.","answers":["were"],"explanation":"Was/were + -ing o‘tmishdagi ma’lum paytda davom etayotgan harakatni bildiradi: I was reading at eight. Past Simple qisqa kiruvchi voqeani beradi: I was reading when the lights went out. Ikki shakl bir hikoyada turli vazifaga ega. While ko‘pincha davom etayotgan ikki ishni bog‘laydi. When va while ni faqat bitta zamonga qamalgan avtomatik signal deb olmang; ma’noni kuzating.","hint":"was/were + -ing … when + Past Simple"},{"id":"en-a2-04-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I was reading at eight."],"explanation":"Was/were + -ing o‘tmishdagi ma’lum paytda davom etayotgan harakatni bildiradi: I was reading at eight. Past Simple qisqa kiruvchi voqeani beradi: I was reading when the lights went out. Ikki shakl bir hikoyada turli vazifaga ega. While ko‘pincha davom etayotgan ikki ishni bog‘laydi. When va while ni faqat bitta zamonga qamalgan avtomatik signal deb olmang; ma’noni kuzating.","hint":"was/were + -ing … when + Past Simple","tokens":["I","was","reading","at","eight."]},{"id":"en-a2-04-fix","type":"correction","skill":"grammar","prompt":"I was read at eight.","answers":["I was reading at eight."],"explanation":"Was/were + -ing o‘tmishdagi ma’lum paytda davom etayotgan harakatni bildiradi: I was reading at eight. Past Simple qisqa kiruvchi voqeani beradi: I was reading when the lights went out. Ikki shakl bir hikoyada turli vazifaga ega. While ko‘pincha davom etayotgan ikki ishni bog‘laydi. When va while ni faqat bitta zamonga qamalgan avtomatik signal deb olmang; ma’noni kuzating.","hint":"was/were + -ing … when + Past Simple"},{"id":"en-a2-04-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["chiroqlar","qo‘ng‘iroq qilmoq","… paytida","to‘satdan"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"was/were + -ing … when + Past Simple","left":["lights","call","while","suddenly"],"options":["chiroqlar","qo‘ng‘iroq qilmoq","… paytida","to‘satdan"]},{"id":"en-a2-04-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["I was reading at eight."],"tokens":["I","was","reading","at","eight."],"hint":"was/were + -ing … when + Past Simple","explanation":"Was/were + -ing o‘tmishdagi ma’lum paytda davom etayotgan harakatni bildiradi: I was reading at eight."},{"id":"en-a2-04-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Was va were: kechagi holat: I ___ at home last night.","answers":["was"],"explanation":"I uchun o‘tmishda was.","hint":"was / were; Was she there? No, she wasn’t.","options":["was","were","am"],"recap":true,"sourceLesson":"Was va were: kechagi holat"},{"id":"en-a2-04-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Past Simple: tugallangan ish va did: O‘tgan savolni tanlang.","answers":["Did you visit the village?"],"explanation":"Did + visit asosiy shakl.","hint":"visited / Did you visit? / didn’t visit","options":["Did you visit the village?","Did you visited the village?","Do you visited the village?"],"recap":true,"sourceLesson":"Past Simple: tugallangan ish va did"},{"id":"en-a2-04-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Noto‘g‘ri fe’llar va o‘tgan hikoya: See ning o‘tgan shakli qaysi?","answers":["saw"],"explanation":"See → saw.","hint":"go → went; see → saw; buy → bought; Did you go?","options":["saw","seed","seeed"],"recap":true,"sourceLesson":"Noto‘g‘ri fe’llar va o‘tgan hikoya"}],"reading":{"title":"Past Continuous va uzilgan harakat — vaziyat","text":"At eight yesterday evening, I was doing my homework. My sister was reading in the same room. Suddenly, the lights went out. We stopped working and looked outside. Our neighbours’ lights were off too. While my father was checking a torch, I called my friend. She was studying when I called, but her lights were working. After twenty minutes, our lights came back on. We finished our homework and went to bed a little later than usual.","sentences":["At eight yesterday evening, I was doing my homework.","My sister was reading in the same room.","Suddenly, the lights went out.","We stopped working and looked outside.","Our neighbours’ lights were off too.","While my father was checking a torch, I called my friend.","She was studying when I called, but her lights were working.","After twenty minutes, our lights came back on.","We finished our homework and went to bed a little later than usual."],"questions":[{"id":"en-a2-04-reading0","type":"choice","skill":"reading","prompt":"Chiroq o‘chganda so‘zlovchi nima qilayotgan edi?","answers":["doing homework"],"explanation":"Was doing homework — fon harakat.","hint":"was/were + -ing … when + Past Simple","options":["doing homework","sleeping","walking outside"]},{"id":"en-a2-04-reading1","type":"choice","skill":"reading","prompt":"Chiroq qancha vaqtdan keyin qaytdi?","answers":["twenty minutes"],"explanation":"After twenty minutes.","hint":"was/were + -ing … when + Past Simple","options":["twenty minutes","two hours","five minutes"]},{"id":"en-a2-04-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"was/were + -ing … when + Past Simple","options":["At eight yesterday evening, I was doing my homework.","My sister was reading in the same room.","Suddenly, the lights went out.","We stopped working and looked outside.","Our neighbours’ lights were off too.","While my father was checking a torch, I called my friend.","She was studying when I called, but her lights were working.","After twenty minutes, our lights came back on.","We finished our homework and went to bed a little later than usual."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"I was doing homework at eight. My sister was reading. Suddenly, the lights went out. I called my friend, but her lights were working. Our lights came back after twenty minutes.","audio":"/english-course/v7.23/en-a2-04.mp3","synthetic":true,"questions":[{"id":"en-a2-04-listening0","type":"choice","skill":"listening","prompt":"Singlisi nima qilayotgan edi?","answers":["reading"],"explanation":"Was reading deyiladi.","hint":"was/were + -ing … when + Past Simple","options":["reading","sleeping","cooking"]},{"id":"en-a2-04-listening1","type":"choice","skill":"listening","prompt":"Chiroq qaytish vaqti?","answers":["twenty minutes"],"explanation":"After twenty minutes.","hint":"was/were + -ing … when + Past Simple","options":["twenty minutes","ten minutes","an hour"]},{"id":"en-a2-04-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["eight","twenty minutes"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"was/were + -ing … when + Past Simple","rows":["Soat","Kutish"]},{"id":"en-a2-04-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["We were talking while Ali was drawing."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"was/were + -ing … when + Past Simple","audio":"/english-course/v7.23/en-a2-04-dictation.mp3","transcript":"We were talking while Ali was drawing."}]},"writing":{"task":"Bir ish qilayotgan paytingizda boshqa voqea yuz bergan hikoya yozing.","audience":"Sinfdagi sherigingiz","minWords":53,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Yesterday I was studying in the library when my phone rang. My brother was waiting outside. He didn’t have his keys, so he asked me for help. While I was putting my books away, the librarian asked me to speak quietly. I said sorry, left the room, and gave my brother the keys.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["I was reading at eight.","The lights went out.","She was writing when I called."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"What were you doing at eight? savoliga javob bering va bitta qisqa voqea qo‘shing.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Bir ish qilayotgan paytingizda boshqa voqea yuz bergan hikoya yozing.","exit":[[{"id":"en-a2-04-exit0","type":"grammarFill","skill":"grammar","prompt":"She ___ writing when I called.","answers":["was"],"explanation":"Was/were + -ing o‘tmishdagi ma’lum paytda davom etayotgan harakatni bildiradi: I was reading at eight. Past Simple qisqa kiruvchi voqeani beradi: I was reading when the lights went out. Ikki shakl bir hikoyada turli vazifaga ega. While ko‘pincha davom etayotgan ikki ishni bog‘laydi. When va while ni faqat bitta zamonga qamalgan avtomatik signal deb olmang; ma’noni kuzating.","hint":"was/were + -ing … when + Past Simple"},{"id":"en-a2-04-exit1","type":"grammarFill","skill":"grammar","prompt":"They were ___ TV. (watch)","answers":["watching"],"explanation":"Was/were + -ing o‘tmishdagi ma’lum paytda davom etayotgan harakatni bildiradi: I was reading at eight. Past Simple qisqa kiruvchi voqeani beradi: I was reading when the lights went out. Ikki shakl bir hikoyada turli vazifaga ega. While ko‘pincha davom etayotgan ikki ishni bog‘laydi. When va while ni faqat bitta zamonga qamalgan avtomatik signal deb olmang; ma’noni kuzating.","hint":"was/were + -ing … when + Past Simple"},{"id":"en-a2-04-exit2","type":"grammarFill","skill":"grammar","prompt":"I was reading ___ the lights went out.","answers":["when"],"explanation":"Was/were + -ing o‘tmishdagi ma’lum paytda davom etayotgan harakatni bildiradi: I was reading at eight. Past Simple qisqa kiruvchi voqeani beradi: I was reading when the lights went out. Ikki shakl bir hikoyada turli vazifaga ega. While ko‘pincha davom etayotgan ikki ishni bog‘laydi. When va while ni faqat bitta zamonga qamalgan avtomatik signal deb olmang; ma’noni kuzating.","hint":"was/were + -ing … when + Past Simple"},{"id":"en-a2-04-exit3","type":"choice","skill":"grammar","prompt":"Qisqa kiruvchi voqea qaysi?","answers":["the lights went out"],"explanation":"Went out Past Simpleda qisqa voqea.","hint":"was/were + -ing … when + Past Simple","options":["the lights went out","I was reading","she was writing"]},{"id":"en-a2-04-exit4","type":"choice","skill":"grammar","prompt":"We bilan davomli o‘tmish yordamchisi?","answers":["were"],"explanation":"We were + -ing.","hint":"was/were + -ing … when + Past Simple","options":["were","was","did"]}],[{"id":"en-a2-04-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The lights went out."],"explanation":"Was/were + -ing o‘tmishdagi ma’lum paytda davom etayotgan harakatni bildiradi: I was reading at eight. Past Simple qisqa kiruvchi voqeani beradi: I was reading when the lights went out. Ikki shakl bir hikoyada turli vazifaga ega. While ko‘pincha davom etayotgan ikki ishni bog‘laydi. When va while ni faqat bitta zamonga qamalgan avtomatik signal deb olmang; ma’noni kuzating.","hint":"was/were + -ing … when + Past Simple","tokens":["The","lights","went","out."]},{"id":"en-a2-04-exit-b1","type":"grammarFill","skill":"grammar","prompt":"They were ___ TV. (watch)","answers":["watching"],"explanation":"Was/were + -ing o‘tmishdagi ma’lum paytda davom etayotgan harakatni bildiradi: I was reading at eight. Past Simple qisqa kiruvchi voqeani beradi: I was reading when the lights went out. Ikki shakl bir hikoyada turli vazifaga ega. While ko‘pincha davom etayotgan ikki ishni bog‘laydi. When va while ni faqat bitta zamonga qamalgan avtomatik signal deb olmang; ma’noni kuzating.","hint":"was/were + -ing … when + Past Simple"},{"id":"en-a2-04-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We were talking while Ali was drawing."],"explanation":"Was/were + -ing o‘tmishdagi ma’lum paytda davom etayotgan harakatni bildiradi: I was reading at eight. Past Simple qisqa kiruvchi voqeani beradi: I was reading when the lights went out. Ikki shakl bir hikoyada turli vazifaga ega. While ko‘pincha davom etayotgan ikki ishni bog‘laydi. When va while ni faqat bitta zamonga qamalgan avtomatik signal deb olmang; ma’noni kuzating.","hint":"was/were + -ing … when + Past Simple","tokens":["We","were","talking","while","Ali","was","drawing."]},{"id":"en-a2-04-exit-b3","type":"choice","skill":"grammar","prompt":"Qisqa kiruvchi voqea qaysi?","answers":["the lights went out"],"explanation":"Went out Past Simpleda qisqa voqea.","hint":"was/were + -ing … when + Past Simple","options":["the lights went out","I was reading","she was writing"]},{"id":"en-a2-04-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["They weren’t watching TV."],"explanation":"Was/were + -ing o‘tmishdagi ma’lum paytda davom etayotgan harakatni bildiradi: I was reading at eight. Past Simple qisqa kiruvchi voqeani beradi: I was reading when the lights went out. Ikki shakl bir hikoyada turli vazifaga ega. While ko‘pincha davom etayotgan ikki ishni bog‘laydi. When va while ni faqat bitta zamonga qamalgan avtomatik signal deb olmang; ma’noni kuzating.","hint":"was/were + -ing … when + Past Simple","tokens":["They","weren’t","watching","TV."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-a2-04-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Was va were: kechagi holat: I ___ at home last night.","answers":["was"],"explanation":"I uchun o‘tmishda was.","hint":"was / were; Was she there? No, she wasn’t.","options":["was","were","am"],"recap":true,"sourceLesson":"Was va were: kechagi holat"},{"id":"en-a2-04-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Past Simple: tugallangan ish va did: O‘tgan savolni tanlang.","answers":["Did you visit the village?"],"explanation":"Did + visit asosiy shakl.","hint":"visited / Did you visit? / didn’t visit","options":["Did you visit the village?","Did you visited the village?","Do you visited the village?"],"recap":true,"sourceLesson":"Past Simple: tugallangan ish va did"},{"id":"en-a2-04-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Noto‘g‘ri fe’llar va o‘tgan hikoya: See ning o‘tgan shakli qaysi?","answers":["saw"],"explanation":"See → saw.","hint":"go → went; see → saw; buy → bought; Did you go?","options":["saw","seed","seeed"],"recap":true,"sourceLesson":"Noto‘g‘ri fe’llar va o‘tgan hikoya"}]}'::json