insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-05','en-a2-05',null,2,5,'published',1,'{"id":"en-a2-05","baseId":"en-a2-05","revision":1,"level":"A2","levelIndex":2,"order":5,"title":"Kelajak: will va going to","objective":"Reja, ko‘rinib turgan taxmin va shu paytdagi qarorni farqlaysiz.","context":"Sinf dam olish kuni kichik sayrni rejalashtiradi.","prerequisites":["en-a2-04"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Be going to oldindan tuzilgan niyat yoki hozirgi dalilga tayangan taxminni ifodalaydi: We’re going to visit the park.","Will ko‘pincha hozir qabul qilingan qaror, taklif va umumiy taxmin uchun: I’ll carry the bag. Shakllar ayrim vaziyatlarda bir-biriga yaqin bo‘lishi mumkin.","Going to uchun am/is/are kerak. Will dan keyin asosiy fe’l keladi. Aniq tashkil qilingan kelajak uchrashuvida Present Continuous ham ishlatiladi."],"pattern":"We are going to … / I will … / We are meeting on Saturday.","examples":["We are going to visit the park.","I’ll carry the bag.","Look at the clouds. It is going to rain.","I think the trip will be fun.","We are meeting at nine.","She isn’t going to stay late."],"vocabulary":[{"id":"en-a2-05-v0","term":"plan","meaning":"reja","ipa":"/plæn/","collocation":"make a plan","example":"We made the plan yesterday and are meeting at nine near school."},{"id":"en-a2-05-v1","term":"cloud","meaning":"bulut","ipa":"/klaʊd/","collocation":"dark clouds","example":"Look at the clouds. It is going to rain."},{"id":"en-a2-05-v2","term":"carry","meaning":"ko‘tarmoq","ipa":"/ˈkæri/","collocation":"carry a bag","example":"I’ll carry the bag."},{"id":"en-a2-05-v3","term":"rain","meaning":"yomg‘ir yog‘moq","ipa":"/reɪn/","collocation":"going to rain","example":"Look at the clouds. It is going to rain."}],"visuals":[{"kind":"timeline","title":"Ma’no va tuzilish","items":["We are going to … / I will … / We are meeting on Saturday.","We are going to visit the park.","I’ll carry the bag."],"timeline":[{"why":"Going to oldindan belgilangan niyatni kelajakdagi tashrif bilan bog‘laydi.","events":[{"kind":"link","from":320,"to":515,"label":"Hozirgi niyat → keyingi tashrif"},{"kind":"point","x":515,"label":"Kelajakdagi tashrif"}]},{"why":"I’ll carry shu vaziyatda bildirilgan yordam taklifi. Harakat oldinda.","events":[{"kind":"link","from":320,"to":480,"label":"Taklif → keyingi yordam"},{"kind":"point","x":480,"label":"Sumkani ko‘tarish"}]}]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Sinf dam olish kuni kichik sayrni rejalashtiradi.","Look at the clouds. It is going to rain.","We are meeting at nine."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"I think the trip will be fun.","audio":"/english-course/v7.23/en-a2-05-dictation.mp3"},"exercises":[{"id":"en-a2-05-choice","type":"choice","skill":"grammar","prompt":"Ko‘rinib turgan dalil bilan taxminni tanlang.","answers":["Look at the clouds. It’s going to rain."],"explanation":"Dark clouds hozirgi dalil.","hint":"We are going to … / I will … / We are meeting on Saturday.","options":["Look at the clouds. It’s going to rain.","It raining yesterday.","We rain clouds."]},{"id":"en-a2-05-gap","type":"grammarFill","skill":"grammar","prompt":"She ___ going to bring water.","answers":["is"],"explanation":"Be going to oldindan tuzilgan niyat yoki hozirgi dalilga tayangan taxminni ifodalaydi: We’re going to visit the park. Will ko‘pincha hozir qabul qilingan qaror, taklif va umumiy taxmin uchun: I’ll carry the bag. Shakllar ayrim vaziyatlarda bir-biriga yaqin bo‘lishi mumkin. Going to uchun am/is/are kerak. Will dan keyin asosiy fe’l keladi. Aniq tashkil qilingan kelajak uchrashuvida Present Continuous ham ishlatiladi.","hint":"We are going to … / I will … / We are meeting on Saturday."},{"id":"en-a2-05-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["We are going to visit the park."],"explanation":"Be going to oldindan tuzilgan niyat yoki hozirgi dalilga tayangan taxminni ifodalaydi: We’re going to visit the park. Will ko‘pincha hozir qabul qilingan qaror, taklif va umumiy taxmin uchun: I’ll carry the bag. Shakllar ayrim vaziyatlarda bir-biriga yaqin bo‘lishi mumkin. Going to uchun am/is/are kerak. Will dan keyin asosiy fe’l keladi. Aniq tashkil qilingan kelajak uchrashuvida Present Continuous ham ishlatiladi.","hint":"We are going to … / I will … / We are meeting on Saturday.","tokens":["We","are","going","to","visit","the","park."]},{"id":"en-a2-05-fix","type":"correction","skill":"grammar","prompt":"I will carrying the bag.","answers":["I will carry the bag."],"explanation":"Be going to oldindan tuzilgan niyat yoki hozirgi dalilga tayangan taxminni ifodalaydi: We’re going to visit the park. Will ko‘pincha hozir qabul qilingan qaror, taklif va umumiy taxmin uchun: I’ll carry the bag. Shakllar ayrim vaziyatlarda bir-biriga yaqin bo‘lishi mumkin. Going to uchun am/is/are kerak. Will dan keyin asosiy fe’l keladi. Aniq tashkil qilingan kelajak uchrashuvida Present Continuous ham ishlatiladi.","hint":"We are going to … / I will … / We are meeting on Saturday."},{"id":"en-a2-05-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["reja","bulut","ko‘tarmoq","yomg‘ir yog‘moq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"We are going to … / I will … / We are meeting on Saturday.","left":["plan","cloud","carry","rain"],"options":["reja","bulut","ko‘tarmoq","yomg‘ir yog‘moq"]}],"reading":{"title":"Kelajak: will va going to — vaziyat","text":"Our class is going to visit a park on Saturday. We made the plan yesterday and are meeting at nine near school. Lola is going to bring water. Ali sees her heavy bag and says, “I’ll carry it.” The teacher looks at the dark clouds and thinks it is going to rain. We decide to take light raincoats. I think the trip will be interesting because a guide will show us different trees. If the weather is very bad, we will visit the indoor museum instead.","sentences":["Our class is going to visit a park on Saturday.","We made the plan yesterday and are meeting at nine near school.","Lola is going to bring water.","Ali sees her heavy bag and says, “I’ll carry it.","” The teacher looks at the dark clouds and thinks it is going to rain.","We decide to take light raincoats.","I think the trip will be interesting because a guide will show us different trees.","If the weather is very bad, we will visit the indoor museum instead."],"questions":[{"id":"en-a2-05-reading0","type":"choice","skill":"reading","prompt":"Oldindan tuzilgan reja nima?","answers":["visit the park"],"explanation":"We made the plan yesterday.","hint":"We are going to … / I will … / We are meeting on Saturday.","options":["visit the park","carry Lola’s bag","cancel school"]},{"id":"en-a2-05-reading1","type":"choice","skill":"reading","prompt":"Yomg‘ir taxmini qaysi dalilga asoslangan?","answers":["dark clouds"],"explanation":"Look at the dark clouds.","hint":"We are going to … / I will … / We are meeting on Saturday.","options":["dark clouds","a broken bag","a long bus ride"]},{"id":"en-a2-05-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"We are going to … / I will … / We are meeting on Saturday.","options":["Our class is going to visit a park on Saturday.","We made the plan yesterday and are meeting at nine near school.","Lola is going to bring water.","Ali sees her heavy bag and says, “I’ll carry it.","” The teacher looks at the dark clouds and thinks it is going to rain.","We decide to take light raincoats.","I think the trip will be interesting because a guide will show us different trees.","If the weather is very bad, we will visit the indoor museum instead."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"We are going to visit the park on Saturday. We are meeting at nine. Lola will bring water. Look at those clouds! It is going to rain, so I’ll bring a raincoat too.","audio":"/english-course/v7.23/en-a2-05.mp3","synthetic":true,"questions":[{"id":"en-a2-05-listening0","type":"choice","skill":"listening","prompt":"Uchrashuv nechada?","answers":["nine"],"explanation":"Meeting at nine.","hint":"We are going to … / I will … / We are meeting on Saturday.","options":["nine","ten","eight"]},{"id":"en-a2-05-listening1","type":"choice","skill":"listening","prompt":"Nima olib keladi?","answers":["a raincoat"],"explanation":"I’ll bring a raincoat.","hint":"We are going to … / I will … / We are meeting on Saturday.","options":["a raincoat","a computer","a blanket"]},{"id":"en-a2-05-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["Saturday","nine"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"We are going to … / I will … / We are meeting on Saturday.","rows":["Kun","Soat"]},{"id":"en-a2-05-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["I think the trip will be fun."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"We are going to … / I will … / We are meeting on Saturday.","audio":"/english-course/v7.23/en-a2-05-dictation.mp3","transcript":"I think the trip will be fun."}]},"writing":{"task":"Dam olish kuni rejasi, bitta taklif va ob-havo taxminini yozing.","audience":"Sinfdagi sherigingiz","minWords":55,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"We are going to visit our cousins on Sunday. We are meeting at the bus stop at ten. I am going to bring a cake. My sister has a heavy bag, so I’ll carry it. I think we will have a good day, but the clouds look dark, so I’m going to take a raincoat.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["We are going to visit the park.","I’ll carry the bag.","Look at the clouds. It is going to rain."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Sherigingiz bilan sayr rejasini kelishing va bir yordam taklif qiling.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Dam olish kuni rejasi, bitta taklif va ob-havo taxminini yozing.","exit":[[{"id":"en-a2-05-exit0","type":"grammarFill","skill":"grammar","prompt":"We ___ going to visit the park.","answers":["are"],"explanation":"Be going to oldindan tuzilgan niyat yoki hozirgi dalilga tayangan taxminni ifodalaydi: We’re going to visit the park. Will ko‘pincha hozir qabul qilingan qaror, taklif va umumiy taxmin uchun: I’ll carry the bag. Shakllar ayrim vaziyatlarda bir-biriga yaqin bo‘lishi mumkin. Going to uchun am/is/are kerak. Will dan keyin asosiy fe’l keladi. Aniq tashkil qilingan kelajak uchrashuvida Present Continuous ham ishlatiladi.","hint":"We are going to … / I will … / We are meeting on Saturday."},{"id":"en-a2-05-exit1","type":"grammarFill","skill":"grammar","